using System;
using Framework.AI.Scheduling;
using UnityEngine;

namespace Game.Tests
{
    /// <summary>
    /// エージェント更新管理システムの基本機能、
    /// 負荷分散および境界条件を検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class AgentUpdateManagerTest : MonoBehaviour
    {
        [Header("テスト設定")]
        [SerializeField]
        [Tooltip("開始時にすべてのテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト結果")]
        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// テスト用の仮想エージェント。
        /// </summary>
        private sealed class TestAgent : IAgentTickable
        {
            /// <summary>
            /// 更新可能かどうか。
            /// </summary>
            public bool IsTickEnabled { get; set; } = true;

            /// <summary>
            /// 更新された回数。
            /// </summary>
            public int TickCount { get; private set; }

            /// <summary>
            /// 最後に受け取った経過時間。
            /// </summary>
            public float LastDeltaTime { get; private set; }

            /// <summary>
            /// 更新時に追加で実行するテスト処理。
            /// </summary>
            public Action OnTick { get; set; }

            /// <summary>
            /// 更新回数と経過時間を記録する。
            /// </summary>
            /// <param name="deltaTime">経過時間。単位は秒</param>
            public void Tick(float deltaTime)
            {
                TickCount++;

                LastDeltaTime = deltaTime;

                OnTick?.Invoke();
            }
        }

        /// <summary>
        /// 開始時のテスト実行を制御する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            if (!Application.isPlaying)
            {
                Debug.LogWarning(
                    "再生モードでテストを実行してください。",
                    this);

                return;
            }

            passedCount = 0;
            failedCount = 0;

            // テスト専用の一時オブジェクトを生成する。
            GameObject testObject =
                new GameObject("AgentUpdateManager_Test");

            var manager =
                testObject.AddComponent<AgentUpdateManager>();

            manager.AutoUpdate = false;

            try
            {
                TestRegistration(manager);
                TestInterval(manager);
                TestDistribution(manager);
                TestUpdateRequest(manager);
                TestPause(manager);
                TestRegistrationDuringTick(manager);
                TestStatistics(manager);
                TestInvalidInput(manager);
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }
            finally
            {
                manager.Clear();

                testObject.SetActive(false);

                Destroy(testObject);
            }

            Debug.Log(
                $"【AgentUpdateManager テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗したテストを確認してください。"),
                this);
        }

        /// <summary>
        /// テスト間で登録情報と統計情報を初期化する。
        /// </summary>
        /// <param name="manager">更新管理システム</param>
        /// <param name="interval">標準更新間隔</param>
        /// <param name="maxUpdates">最大実行件数</param>
        /// <param name="stagger">初回更新を分散するか</param>
        private void Prepare(
            AgentUpdateManager manager,
            float interval = 0.25f,
            int maxUpdates = 8,
            bool stagger = false)
        {
            manager.Clear();

            manager.Resume();

            manager.ResetStatistics();

            manager.Configure(
                new AgentUpdateSettings(
                    interval,
                    maxUpdates,
                    stagger));
        }

        /// <summary>
        /// 登録および登録解除を検証する。
        /// </summary>
        /// <param name="manager">更新管理システム</param>
        private void TestRegistration(
            AgentUpdateManager manager)
        {
            Prepare(manager);

            var agent = new TestAgent();

            bool emptyPassed =
                manager.RegisteredCount == 0;
            Debug.Assert(emptyPassed, "初期登録件数", this);
            Check(emptyPassed, "初期登録件数");

            bool registerPassed =
                manager.TryRegister(agent) &&
                manager.RegisteredCount == 1;
            Debug.Assert(registerPassed, "エージェントの登録", this);
            Check(registerPassed, "エージェントの登録");

            bool duplicatePassed =
                !manager.TryRegister(agent) &&
                manager.RegisteredCount == 1;
            Debug.Assert(duplicatePassed, "重複登録の拒否", this);
            Check(duplicatePassed, "重複登録の拒否");

            bool containsPassed = manager.Contains(agent);
            Debug.Assert(containsPassed, "登録状態の検索", this);
            Check(containsPassed, "登録状態の検索");

            bool removePassed =
                manager.TryUnregister(agent) &&
                !manager.Contains(agent) &&
                !manager.TryUnregister(agent) &&
                manager.RegisteredCount == 0;
            Debug.Assert(removePassed, "登録解除と再解除", this);
            Check(removePassed, "登録解除と再解除");
        }

        /// <summary>
        /// 更新間隔と経過時間の管理を検証する。
        /// </summary>
        /// <param name="manager">更新管理システム</param>
        private void TestInterval(
            AgentUpdateManager manager)
        {
            Prepare(manager);

            var agent = new TestAgent();

            manager.TryRegister(agent);

            manager.Tick(0.125f);

            bool waitingPassed = agent.TickCount == 0;
            Debug.Assert(waitingPassed, "更新予定前の待機", this);
            Check(waitingPassed, "更新予定前の待機");

            manager.Tick(0.125f);

            bool intervalPassed = agent.TickCount == 1;
            Debug.Assert(intervalPassed, "更新予定到達時の実行", this);
            Check(intervalPassed, "更新予定到達時の実行");

            bool deltaPassed =
                Mathf.Approximately(
                    agent.LastDeltaTime,
                    0.25f);
            Debug.Assert(deltaPassed, "経過時間の通知", this);
            Check(deltaPassed, "経過時間の通知");

            manager.Tick(1f);

            bool longFramePassed =
                agent.TickCount == 2 &&
                Mathf.Approximately(
                    agent.LastDeltaTime,
                    1f);
            Debug.Assert(longFramePassed, "長時間経過時の単一更新", this);
            Check(longFramePassed, "長時間経過時の単一更新");

            manager.TrySetInterval(agent, 0.5f);

            manager.Tick(0.25f);

            bool waiting = agent.TickCount == 2;

            manager.Tick(0.25f);

            bool changedPassed =
                waiting && agent.TickCount == 3;
            Debug.Assert(changedPassed, "個別更新間隔の変更", this);
            Check(changedPassed, "個別更新間隔の変更");
        }

        /// <summary>
        /// 最大実行件数と更新タイミングの分散を検証する。
        /// </summary>
        /// <param name="manager">更新管理システム</param>
        private void TestDistribution(
            AgentUpdateManager manager)
        {
            Prepare(manager, 0.25f, 2);

            var agents = new TestAgent[5];

            for (int i = 0; i < agents.Length; i++)
            {
                agents[i] = new TestAgent();

                manager.TryRegister(agents[i]);
            }

            manager.Tick(0.25f);

            bool budgetPassed =
                manager.LastTickUpdateCount == 2;
            Debug.Assert(budgetPassed, "最大実行件数の制限", this);
            Check(budgetPassed, "最大実行件数の制限");

            manager.Tick(0.0625f);

            bool nextPassed =
                agents[2].TickCount == 1 &&
                agents[3].TickCount == 1;
            Debug.Assert(nextPassed, "次の個体への更新分散", this);
            Check(nextPassed, "次の個体への更新分散");

            manager.Tick(0.0625f);

            bool fairnessPassed =
                agents[4].TickCount == 1;
            Debug.Assert(fairnessPassed, "後続個体の更新保証", this);
            Check(fairnessPassed, "後続個体の更新保証");

            bool totalPassed =
                manager.TotalUpdateCount == 5;
            Debug.Assert(totalPassed, "分散更新の累計件数", this);
            Check(totalPassed, "分散更新の累計件数");

            Prepare(manager, 1f, 8, true);

            for (int i = 0; i < 8; i++)
            {
                manager.TryRegister(new TestAgent());
            }

            manager.Tick(0.5f);

            bool staggerPassed =
                manager.LastTickUpdateCount > 0 &&
                manager.LastTickUpdateCount < 8;
            Debug.Assert(staggerPassed, "初回更新タイミングの分散", this);
            Check(staggerPassed, "初回更新タイミングの分散");
        }

        /// <summary>
        /// 更新要求と要求の重複防止を検証する。
        /// </summary>
        /// <param name="manager">更新管理システム</param>
        private void TestUpdateRequest(
            AgentUpdateManager manager)
        {
            Prepare(manager, 1f, 1);

            var first = new TestAgent();
            var second = new TestAgent();

            manager.TryRegister(first);
            manager.TryRegister(second);

            bool requestPassed =
                manager.RequestUpdate(first) &&
                first.TickCount == 0;
            Debug.Assert(requestPassed, "更新要求の登録", this);
            Check(requestPassed, "更新要求の登録");

            manager.RequestUpdate(first);
            manager.RequestUpdate(first);
            manager.RequestUpdate(second);

            manager.Tick(0.125f);

            bool immediatePassed =
                first.TickCount == 1 &&
                second.TickCount == 0;
            Debug.Assert(immediatePassed, "要求時の前倒し更新", this);
            Check(immediatePassed, "要求時の前倒し更新");

            manager.Tick(0.125f);

            bool limitPassed =
                first.TickCount == 1 &&
                second.TickCount == 1;
            Debug.Assert(limitPassed, "要求の統合と実行件数制限", this);
            Check(limitPassed, "要求の統合と実行件数制限");

            bool missingPassed =
                !manager.RequestUpdate(new TestAgent());
            Debug.Assert(missingPassed, "未登録対象への更新要求拒否", this);
            Check(missingPassed, "未登録対象への更新要求拒否");
        }

        /// <summary>
        /// 一時停止とエージェントの無効状態を検証する。
        /// </summary>
        /// <param name="manager">更新管理システム</param>
        private void TestPause(
            AgentUpdateManager manager)
        {
            Prepare(manager);

            var agent = new TestAgent();

            manager.TryRegister(agent);

            double beforePause = manager.ElapsedTime;

            manager.Pause();

            manager.Tick(1f);

            bool pausePassed =
                agent.TickCount == 0 &&
                manager.IsPaused;
            Debug.Assert(pausePassed, "一時停止中の更新抑止", this);
            Check(pausePassed, "一時停止中の更新抑止");

            bool timePassed =
                manager.ElapsedTime == beforePause;
            Debug.Assert(timePassed, "一時停止中の時間停止", this);
            Check(timePassed, "一時停止中の時間停止");

            manager.Resume();

            manager.Tick(0.25f);

            bool resumePassed =
                agent.TickCount == 1 &&
                !manager.IsPaused;
            Debug.Assert(resumePassed, "更新処理の再開", this);
            Check(resumePassed, "更新処理の再開");

            agent.IsTickEnabled = false;

            manager.Tick(1f);

            bool disabledPassed =
                agent.TickCount == 1;
            Debug.Assert(disabledPassed, "無効個体の更新抑止", this);
            Check(disabledPassed, "無効個体の更新抑止");
        }

        /// <summary>
        /// 更新処理中の登録変更を検証する。
        /// </summary>
        /// <param name="manager">更新管理システム</param>
        private void TestRegistrationDuringTick(
            AgentUpdateManager manager)
        {
            Prepare(manager);

            var first = new TestAgent();
            var second = new TestAgent();
            var third = new TestAgent();

            first.OnTick = () =>
            {
                manager.TryUnregister(first);

                manager.TryUnregister(second);

                manager.TryRegister(third);
            };

            manager.TryRegister(first);
            manager.TryRegister(second);

            manager.Tick(0.25f);

            bool selfPassed =
                first.TickCount == 1 &&
                !manager.Contains(first);
            Debug.Assert(selfPassed, "更新中の自己登録解除", this);
            Check(selfPassed, "更新中の自己登録解除");

            bool otherPassed =
                second.TickCount == 0 &&
                !manager.Contains(second);
            Debug.Assert(otherPassed, "更新中の他個体登録解除", this);
            Check(otherPassed, "更新中の他個体登録解除");

            bool newPassed =
                third.TickCount == 0 &&
                manager.RegisteredCount == 1 &&
                manager.Contains(third);
            Debug.Assert(newPassed, "更新中の新規登録", this);
            Check(newPassed, "更新中の新規登録");

            manager.Tick(0.25f);

            bool nextPassed =
                third.TickCount == 1;
            Debug.Assert(nextPassed, "新規登録個体の次回更新", this);
            Check(nextPassed, "新規登録個体の次回更新");
        }

        /// <summary>
        /// 統計情報と更新設定の変更を検証する。
        /// </summary>
        /// <param name="manager">更新管理システム</param>
        private void TestStatistics(
            AgentUpdateManager manager)
        {
            Prepare(manager);

            var agent = new TestAgent();

            manager.TryRegister(agent);

            manager.Tick(0.25f);
            manager.Tick(0.25f);

            bool statisticsPassed =
                manager.TotalUpdateCount == 2 &&
                manager.LastTickUpdateCount == 1;
            Debug.Assert(statisticsPassed, "更新統計の記録", this);
            Check(statisticsPassed, "更新統計の記録");

            manager.ResetStatistics();

            bool resetPassed =
                manager.TotalUpdateCount == 0 &&
                manager.LastTickUpdateCount == 0 &&
                manager.RegisteredCount == 1;
            Debug.Assert(resetPassed, "統計情報のみのリセット", this);
            Check(resetPassed, "統計情報のみのリセット");

            manager.Configure(
                new AgentUpdateSettings(
                    0.5f,
                    4,
                    false));

            bool settingsPassed =
                manager.Settings.UpdateInterval == 0.5f &&
                manager.Settings.MaxUpdatesPerTick == 4;
            Debug.Assert(settingsPassed, "更新管理設定の変更", this);
            Check(settingsPassed, "更新管理設定の変更");
        }

        /// <summary>
        /// 不正な引数が拒否されることを検証する。
        /// </summary>
        /// <param name="manager">更新管理システム</param>
        private void TestInvalidInput(
            AgentUpdateManager manager)
        {
            Prepare(manager);

            bool nullPassed =
                Throws<ArgumentNullException>(() =>
                {
                    manager.TryRegister(null);
                });
            Debug.Assert(nullPassed, "null個体の登録拒否", this);
            Check(nullPassed, "null個体の登録拒否");

            bool intervalPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    manager.TryRegister(
                        new TestAgent(),
                        0f);
                });
            Debug.Assert(intervalPassed, "不正更新間隔の拒否", this);
            Check(intervalPassed, "不正更新間隔の拒否");

            bool timePassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    manager.Tick(-1f);
                });
            Debug.Assert(timePassed, "負の経過時間の拒否", this);
            Check(timePassed, "負の経過時間の拒否");

            bool settingsPassed =
                Throws<ArgumentOutOfRangeException>(() =>
                {
                    new AgentUpdateSettings(0.25f, 0);
                });
            Debug.Assert(settingsPassed, "不正実行件数の拒否", this);
            Check(settingsPassed, "不正実行件数の拒否");
        }

        /// <summary>
        /// 指定された処理が期待する例外を発生させるか検証する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">検証対象の処理</param>
        /// <returns>期待する例外が発生した場合はtrue</returns>
        private bool Throws<TException>(Action action)
            where TException : Exception
        {
            try
            {
                action();
            }
            catch (Exception exception)
            {
                if (exception.GetType() == typeof(TException))
                {
                    return true;
                }

                throw;
            }

            return false;
        }

        /// <summary>
        /// 個別のテスト結果を出力し、結果を集計する。
        /// </summary>
        /// <param name="passed">テストの成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
